operations.schema:
input SetTitleInput {
    title: String
}

input SetDescriptionInput {
    description: String
}

input SetProvenanceInput {
    queue: PHID
    system: String
    detail: Unknown
}

operations.reducer:
state.provenance = {
  queue: action.input.queue ?? null,
  system: action.input.system ?? null,
  detail: action.input.detail ?? null,
};

operations.schema:
input DiscardCollectionInput {
    _: Boolean
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
if (state.status === "DISCARDED") {
  throw new CollectionAlreadyDiscardedError(
    "This collection has already been abandoned.",
  );
}
// Sticky: recalculate leaves DISCARDED alone, because abandoning a
// collection is a decision and a roll-up would undo it on the next
// operation.
state.status = "DISCARDED";
recalculate(state);

operations.schema:
input RestoreCollectionInput {
    _: Boolean
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
if (state.status !== "DISCARDED") {
  throw new CollectionNotDiscardedError(
    "This collection is live, so there is nothing to restore; its status is calculated from its sources.",
  );
}
// Anything not DISCARDED lets the roll-up take over again.
state.status = "NEW";
recalculate(state);

// requires: import { recalculate } from "../derived.js";
// requires: import { aliasesWith, claimantsOf, identifiersToAbsorb,
//                    isNamespaced, pickWinner, union } from "../identity.js";
if (state.status === "DISCARDED") {
  throw new CaptureIntoDiscardedCollectionError(
    "This collection has been abandoned; capturing into it would add to something nobody is reading. Restore it first.",
  );
}

const incoming = [action.input.externalId, ...(action.input.aliases ?? [])].map(
  (value) => value.trim(),
);

for (const identifier of incoming) {
  if (!isNamespaced(identifier)) {
    throw new CaptureUnnamespacedIdentifierError(
      `Identifier "${identifier}" does not name the system it came from. Use system:value, for example gmail:18f3a — without it, an id from one system and an id from another are the same key.`,
    );
  }
}

const claimants = claimantsOf(state.sources, incoming);

if (claimants.length === 0) {
  if (state.sources.some((source) => source.id === action.input.id)) {
    throw new CaptureSourceIdTakenError(
      `No source claims these identifiers, so this capture creates one — but OID ${action.input.id} is already taken. Supply a fresh id.`,
    );
  }
  state.sources.push({
    id: action.input.id,
    status: "NEW",
    externalId: action.input.externalId.trim(),
    aliases: union([], action.input.aliases ?? []),
    title: action.input.title ?? null,
    origin: action.input.origin ?? null,
    content: action.input.content ?? null,
    payload: action.input.payload ?? null,
    attachments: (action.input.attachments ?? []).map((file) => ({
      ref: file.ref,
      fileName: file.fileName,
      sizeBytes: file.sizeBytes ?? null,
      mimeType: file.mimeType ?? null,
    })),
    references: action.input.references ?? [],
    tags: union([], action.input.tags ?? []),
    occurredAt: action.input.occurredAt ?? null,
    capturedAt: action.input.capturedAt,
    mergedInto: null,
    mergedAt: null,
    mergedFrom: [],
  });
  recalculate(state);
  return;
}

// More than one live source answers to these identifiers, so this record is
// evidence they are the same object. Folding them together here was a
// deliberate choice: the tombstones make it auditable, and SPLIT_SOURCE makes
// it reversible, which is what keeps an automatic merge from being an
// irreversible decision taken by a side effect.
const winner = pickWinner(claimants);
for (const loser of claimants) {
  if (loser.id === winner.id) continue;
  winner.aliases = aliasesWith(winner, identifiersToAbsorb(winner, loser));
  loser.status = "DISCARDED";
  loser.mergedInto = winner.id;
  // From the input, never a clock: a reducer has to replay identically.
  loser.mergedAt = action.input.capturedAt;
}

// Provided fields overwrite; absent ones are left alone. Sets are unioned and
// never emptied by a capture — a later sighting that happens to omit a tag is
// not a decision to remove it.
const target = winner;
target.aliases = aliasesWith(target, incoming);
if (action.input.title !== undefined && action.input.title !== null) {
  target.title = action.input.title;
}
if (action.input.origin !== undefined && action.input.origin !== null) {
  target.origin = action.input.origin;
}
if (action.input.content !== undefined && action.input.content !== null) {
  target.content = action.input.content;
}
if (action.input.payload !== undefined && action.input.payload !== null) {
  target.payload = action.input.payload;
}
if (action.input.occurredAt) target.occurredAt = action.input.occurredAt;
target.capturedAt = action.input.capturedAt;
target.tags = union(target.tags, action.input.tags ?? []);
target.references = union(target.references, action.input.references ?? []);
for (const file of action.input.attachments ?? []) {
  if (target.attachments.some((held) => held.ref === file.ref)) continue;
  target.attachments.push({
    ref: file.ref,
    fileName: file.fileName,
    sizeBytes: file.sizeBytes ?? null,
    mimeType: file.mimeType ?? null,
  });
}

recalculate(state);

const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new AttachSourceNotFoundError(
    `There is no source ${action.input.source} to attach to.`,
  );
}
if (source.attachments.some((held) => held.ref === action.input.ref)) {
  throw new AttachRefAlreadyPresentError(
    "That file is already attached to this source; attachments are content-addressed, so the same ref is the same bytes.",
  );
}

source.attachments.push({
  ref: action.input.ref,
  fileName: action.input.fileName,
  sizeBytes: action.input.sizeBytes ?? null,
  mimeType: action.input.mimeType ?? null,
});

operations.schema:
input DetachFromSourceInput {
    source: OID!
    ref: AttachmentRef!
}

operations.reducer:
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new DetachSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
const index = source.attachments.findIndex(
  (held) => held.ref === action.input.ref,
);
if (index === -1) {
  throw new DetachRefNotFoundError(
    "That file is not attached to this source.",
  );
}
// Only the reference goes; the bytes stay in the store, because this
// operation is for a mis-attachment, not for destroying evidence.
source.attachments.splice(index, 1);

operations.schema:
input AddSourceReferenceInput {
    source: OID!
    reference: URL!
}

operations.reducer:
// requires: import { union } from "../identity.js";
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new ReferenceSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
source.references = union(source.references, [action.input.reference]);

operations.schema:
input AddAliasInput {
    source: OID!
    alias: String!
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
// requires: import { aliasesWith, claimantOf, isNamespaced } from "../identity.js";
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new AddAliasSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
const alias = action.input.alias.trim();
if (!isNamespaced(alias)) {
  throw new AddAliasUnnamespacedError(
    `Alias "${alias}" does not name the system it came from. Use system:value, for example gmail:18f3a.`,
  );
}

const holder = claimantOf(state.sources, alias);
if (holder && holder.id !== source.id) {
  // Deliberately not an automatic merge. Capture folds sources together
  // because a record arriving under both ids is evidence; someone typing an
  // alias by hand is not, so this asks them to mean it.
  throw new AliasAlreadyClaimedError(
    `Source ${holder.id} already answers to "${alias}". An identifier belongs to one source; if these are the same object, merge them.`,
  );
}

source.aliases = aliasesWith(source, [alias]);
recalculate(state);

operations.schema:
input RemoveAliasInput {
    source: OID!
    alias: String!
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new RemoveAliasSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
const alias = action.input.alias.trim();
if (alias === source.externalId) {
  throw new CannotRemoveCanonicalIdentifierError(
    `"${alias}" is this source's canonical externalId, not an alias. Removing it would leave the source unaddressable by the system it came from.`,
  );
}
if (!source.aliases.includes(alias)) {
  throw new AliasNotFoundError(`This source does not answer to "${alias}".`);
}
source.aliases = source.aliases.filter((held) => held !== alias);
recalculate(state);

operations.schema:
input MergeSourcesInput {
    keep: OID!
    merge: [OID!]!
    mergedAt: DateTime!
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
// requires: import { aliasesWith, identifiersToAbsorb, isMerged } from "../identity.js";
const winner = state.sources.find((s) => s.id === action.input.keep);
if (!winner) {
  throw new MergeKeepNotFoundError(
    `There is no source ${action.input.keep} to keep.`,
  );
}

// Everything is validated before anything is written: a merge that fails
// halfway would leave some sources folded and others not, with no record of
// which.
const losers = action.input.merge.map((id) => {
  if (id === winner.id) {
    throw new CannotMergeSourceIntoItselfError(
      `Source ${id} cannot be folded into itself.`,
    );
  }
  const loser = state.sources.find((s) => s.id === id);
  if (!loser) {
    throw new MergeSourceNotFoundError(`There is no source ${id}.`);
  }
  if (isMerged(loser)) {
    throw new MergeAlreadyMergedError(
      `Source ${id} was already folded into ${String(loser.mergedInto)}. Split it first if that was wrong.`,
    );
  }
  return loser;
});

for (const loser of losers) {
  winner.aliases = aliasesWith(winner, identifiersToAbsorb(winner, loser));
  loser.status = "DISCARDED";
  loser.mergedInto = winner.id;
  loser.mergedAt = action.input.mergedAt;
}
recalculate(state);

operations.schema:
input SplitSourceInput {
    source: OID!
    status: OriginalSourceStatus
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
// requires: import { identifiersToReturn, isMerged } from "../identity.js";
const loser = state.sources.find((s) => s.id === action.input.source);
if (!loser) {
  throw new SplitSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
if (!isMerged(loser)) {
  throw new SourceNotMergedError(
    "That source stands on its own, so there is no merge to undo.",
  );
}

const winner = state.sources.find((s) => s.id === loser.mergedInto);
if (winner) {
  // Take back only what this loser brought and nothing else still depends
  // on — undoing one merge must not quietly break another.
  const returning = new Set(identifiersToReturn(state.sources, winner, loser));
  winner.aliases = winner.aliases.filter((alias) => !returning.has(alias));
}

loser.mergedInto = null;
loser.mergedAt = null;
loser.status = action.input.status ?? "NEW";
recalculate(state);

operations.schema:
input SetSourceTitleInput {
    source: OID!
    title: String
}

operations.reducer:
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new SetSourceTitleNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
source.title = action.input.title ?? null;

operations.schema:
input TagSourceInput {
    source: OID!
    tags: [String!]!
}

operations.reducer:
// requires: import { union } from "../identity.js";
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new TagSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
// A set: tagging twice is not an error, because a flow that re-runs should
// not have to check first.
source.tags = union(source.tags, action.input.tags);

operations.schema:
input UntagSourceInput {
    source: OID!
    tags: [String!]!
}

operations.reducer:
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new UntagSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
const removing = new Set(action.input.tags.map((tag) => tag.trim()));
source.tags = source.tags.filter((tag) => !removing.has(tag));

operations.schema:
input SetSourceStatusInput {
    source: OID!
    status: OriginalSourceStatus!
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
// requires: import { isMerged } from "../identity.js";
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new SetSourceStatusNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
if (isMerged(source)) {
  // Its DISCARDED status IS the record of the merge. Letting this change it
  // would leave a source that is folded into another while claiming to be
  // live.
  throw new CannotRestatusMergedSourceError(
    `Source ${source.id} was folded into ${String(source.mergedInto)}, so its status records that. Split it first if it should stand on its own again.`,
  );
}
source.status = action.input.status;
recalculate(state);

operations.schema:
input DiscardSourceInput {
    source: OID!
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
const source = state.sources.find((s) => s.id === action.input.source);
if (!source) {
  throw new DiscardSourceNotFoundError(
    `There is no source ${action.input.source}.`,
  );
}
// Discarding something already folded in is harmless — it is already
// discarded — so this one does not refuse.
source.status = "DISCARDED";
recalculate(state);

// requires: import { recalculate } from "../derived.js";
if (state.tasks.some((task) => task.id === action.input.id)) {
  throw new TaskIdTakenError(
    `A task with id ${action.input.id} already exists.`,
  );
}
const source = action.input.source ?? null;
if (source && !state.sources.some((s) => s.id === source)) {
  throw new TaskSourceNotFoundError(
    `This task points at source ${source}, which does not exist. Leave it out to raise a task about the whole batch.`,
  );
}

state.tasks.push({
  id: action.input.id,
  status: action.input.status ?? "TODO",
  owner: action.input.owner ?? null,
  description: action.input.description ?? null,
  source,
  createdAt: action.input.createdAt,
});
recalculate(state);

operations.schema:
input SetTaskStatusInput {
    task: OID!
    status: ProcessingTaskStatus!
}

operations.reducer:
// requires: import { recalculate } from "../derived.js";
const task = state.tasks.find((t) => t.id === action.input.task);
if (!task) {
  throw new SetTaskStatusNotFoundError(
    `There is no task ${action.input.task}.`,
  );
}
task.status = action.input.status;
recalculate(state);

operations.schema:
input AssignTaskInput {
    task: OID!
    owner: String
}

operations.reducer:
const task = state.tasks.find((t) => t.id === action.input.task);
if (!task) {
  throw new AssignTaskNotFoundError(`There is no task ${action.input.task}.`);
}
// Clearing an owner is a legitimate act, not a missing argument.
task.owner = action.input.owner ?? null;

operations.schema:
input SetTaskDescriptionInput {
    task: OID!
    description: String
}

operations.reducer:
const task = state.tasks.find((t) => t.id === action.input.task);
if (!task) {
  throw new SetTaskDescriptionNotFoundError(
    `There is no task ${action.input.task}.`,
  );
}
task.description = action.input.description ?? null;
